fun chooseTool(visibleToUser: Boolean, exactTime: Boolean, mustSurviveRestart: Boolean): String = when {
    visibleToUser -> "служба переднего плана"
    exactTime -> "будильник"
    mustSurviveRestart -> "WorkManager"
    else -> "корутина"
}

fun main() {
    println(chooseTool(true, false, false))
    println(chooseTool(false, true, false))
    println(chooseTool(false, false, true))
    println(chooseTool(false, false, false))
}

class SyncWorker(context: Context, params: WorkerParameters) : CoroutineWorker(context, params) {
    override suspend fun doWork(): Result {
        return try {
            syncTasks()
            Result.success()
        } catch (e: IOException) {
            if (runAttemptCount < 3) Result.retry() else Result.failure()
        }
    }
}

val request = PeriodicWorkRequestBuilder<SyncWorker>(1, TimeUnit.HOURS)
    .setConstraints(
        Constraints.Builder()
            .setRequiredNetworkType(NetworkType.CONNECTED)
            .setRequiresBatteryNotLow(true)
            .build()
    )
    .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS)
    .build()

WorkManager.getInstance(context)
    .enqueueUniquePeriodicWork("sync", ExistingPeriodicWorkPolicy.KEEP, request)

fun retryDelay(attempt: Int): Int = minOf(30 * (1 shl (attempt - 1)), 18000)

fun periodMinutes(requested: Int): Int = maxOf(requested, 15)

fun main() {
    for (a in listOf(1, 2, 3, 6, 12)) println("попытка $a: ${retryDelay(a)} с")
    println(periodMinutes(5))
    println(periodMinutes(60))
}

