fun versionCode(name: String): Int {
    val p = name.split(".").map { it.toInt() }
    return p[0] * 10000 + p[1] * 100 + p[2]
}

fun main() {
    println(versionCode("1.0.0"))
    println(versionCode("1.2.3"))
    println(versionCode("2.10.5"))
    println(versionCode("1.2.3") < versionCode("1.10.0"))
}
